import {createTrainSession} from '@nautilus-engine/map-core/trains';
import {createWorld} from '@nautilus-engine/map-core/world';
import {createInteractionState,createInteractionActor,createInteractionQueries,walkActor} from '@nautilus-engine/map-core/interactions';

// Independent retained application policy; every engine import is public.
// This proof supplies one player and manual cabs, not operator-driven services.
export function createConsumerHost(fixture){
  let actors=structuredClone(fixture.actors),session,disposals=0;const world=createWorld(fixture.world);world.surfaces=fixture.surfaces;
  const interactions=createInteractionState({worldId:world.id}),base=createInteractionQueries(world),get=id=>actors.find(a=>a.id===id);
  function clear(p,a){if(p.h!==0||p.x<a.radiusM||p.y<a.radiusM||p.x>240-a.radiusM||p.y>180-a.radiusM)return false;for(const {state}of session.read().trains)for(const car of state.cars){const c=Math.cos(car.yaw),s=Math.sin(car.yaw),dx=p.x-car.x,dy=p.y-car.z;if(Math.abs(dx*c-dy*s)<1.25+a.radiusM&&Math.abs(dx*s+dy*c)<car.lengthM/2+a.radiusM)return false;}return true;}
  const retained={readActor:id=>structuredClone(get(id)),canEnter({actor,entrance}){if(entrance.mode==='rider')return {ok:false,code:'OPERATOR_NOT_BOUND',reason:'This independent consumer binds manual cabs only.'};return clear(actor.position,actor)?{ok:true}:{ok:false,code:'ACCESS_BLOCKED',reason:'Approach on clear ground.'};},landing({actor,entrance}){const offset=Math.max(.55,1.25+actor.radiusM+.15-Math.abs(entrance.local.x)),landing={position:{x:entrance.position.x+entrance.outward.x*offset,y:entrance.position.y+entrance.outward.y*offset,h:0},floorId:'floor-0',surfaceId:'yard'};return base.landing({state:interactions,actor,landing}).ok&&clear(landing.position,actor)?{ok:true,landing}:{ok:false,code:'LANDING_BLOCKED',reason:'Clear the supported landing.'};},commit({changes}){if(changes.some(c=>get(c.actorId).revision!==c.expectedRevision))return {ok:false,code:'STALE_ACTOR',reason:'Actor changed.'};const next=structuredClone(actors);for(const c of changes)Object.assign(next.find(a=>a.id===c.actorId),c.patch,{revision:c.expectedRevision+1});actors=next;return {ok:true};}};
  session=createTrainSession({routes:fixture.routes,placements:fixture.placements,actorIds:actors.map(a=>a.id),host:retained});const listeners=new Set(),emit=()=>listeners.forEach(fn=>fn()),unsubscribe=session.subscribe(emit);
  const queries={...base,walk(q){const supported=base.walk(q);if(!supported.ok)return supported;const count=Math.max(1,Math.ceil(Math.hypot(q.to.x-q.from.x,q.to.y-q.from.y)/.1));for(let i=1;i<=count;i++)if(!clear({x:q.from.x+(q.to.x-q.from.x)*i/count,y:q.from.y+(q.to.y-q.from.y)*i/count,h:0},q.actor))return {ok:false,code:'WALK_BLOCKED',reason:'Walk around the train.'};return {ok:true};}};
  return {connector:{contract:session.contract,readForActor:id=>session.readForActor(id),dispatch:c=>session.dispatch(c),subscribe(fn){listeners.add(fn);return ()=>listeners.delete(fn);}},get actors(){return structuredClone(actors);},get disposals(){return disposals;},read:()=>session.read(),walk(x,y,seconds){const a=get('player');if(a.mode!=='on-foot')return {ok:false,code:'ABOARD',reason:'Exit first.'};const mover=createInteractionActor({id:a.id,floorId:a.floorId,position:a.position,radiusM:a.radiusM,heightM:a.heightM,speedMps:a.speedMps});mover.revision=a.revision;const n=Math.max(1,Math.hypot(x,y)),r=walkActor(interactions,mover,{direction:{x:x/n,y:y/n},seconds},queries);if(r.ok){Object.assign(a,r.actor);emit();}return r;},advance:seconds=>session.advance(seconds),dispose(){if(disposals)return;disposals++;unsubscribe();session.dispose();listeners.clear();}};
}
